def merge_sorted_lists(list1, list2):
    list1_index, list2_index, merged_list = 0, 0, []
    while list1_index < len(list1) and list2_index < len(list2):
        if list1[list1_index] <= list2[list2_index]:
            merged_list.append(list1[list1_index]); list1_index += 1
        else:
            merged_list.append(list2[list2_index]); list2_index += 1
    merged_list.extend(list1[list1_index:]); merged_list.extend(list2[list2_index:])
    return merged_list

